429	  /** The person's patrons' due-totals added up, skipping the n/a ones; 0.00 with no patrons. */
430	  protected backingOf(person: Person): string {
431	    return sumDues(this.patronsListOf(person).map((p) => this.dueTotalOf(p)));
432	  }
433	
434	  /** The people the person could still name as a patron: everyone else on the sheet not already named. */
435	  protected patronOptions(person: Person): Person[] {
436	    return this.people().filter((p) => p.id !== person.id && !person.patronIds.includes(p.id));
437	  }
438	
439	  protected setPatronChoice(id: number, choice: string): void {
440	    this.patronChoices.update((choices) => ({ ...choices, [id]: choice }));
441	    if (this.patronError()?.id === id) this.patronError.set(null);
442	  }
443	
444	  /** Name the chosen person as the person's patron, then re-read so the backing shows what the store holds. */
445	  protected async addPatron(person: Person): Promise<void> {
446	    this.rowError.set(null);
447	    this.patronError.set(null);
448	    const sheet = this.session.sheet();
449	    if (!sheet) return;
450	    const patronId = Number(this.patronChoices()[person.id] ?? '');
451	    if (!patronId) {
452	      this.patronError.set({ id: person.id, message: 'Choose a person to name as a patron.' });
453	      return;
454	    }
455	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/patrons`;
456	    try {
457	      const saved = await firstValueFrom(this.http.post<Person>(url, { patronId }, this.session.headers()));
458	      if (this.session.sheet() === sheet) {
459	        this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
460	        this.patronChoices.update((choices) => ({ ...choices, [person.id]: '' }));
461	        void this.read(sheet);
462	      }
463	    } catch {
464	      const patron = this.byId().get(patronId)?.name ?? 'That person';
465	      this.patronError.set({ id: person.id, message: `${patron} could not be named a patron of ${person.name}.` });
466	    }
467	  }
468	
469	  private patronsListOf(person: Person): Person[] {
470	    return person.patronIds.map((id) => this.byId().get(id)).filter((p): p is Person => p !== undefined);
471	  }
472	
473	  /** Show a set rate at once, then re-read so the screen holds what the store does. */
474	  protected rateSaved(rate: Rate): void {
475	    const sheet = this.session.sheet();
476	    if (!sheet) return;
477	    this.rates.update((list) =>
478	      [...list.filter((r) => r.grade !== rate.grade || r.from !== rate.from), rate].sort(
479	        (a, b) => a.grade.localeCompare(b.grade) || (a.from ?? '').localeCompare(b.from ?? ''),
480	      ),
481	    );
482	    void this.read(sheet);
483	  }
484	
485	  /** Show an added period at once, then re-read so the screen holds what the store does. */
486	  protected periodSaved(period: Period): void {
487	    const sheet = this.session.sheet();
488	    if (!sheet) return;
489	    this.periods.update((list) =>
490	      [...list.filter((p) => p.id !== period.id), period].sort((a, b) => a.from.localeCompare(b.from)),
491	    );
492	    void this.read(sheet);
493	  }
494	
495	  /** Show an added or saved claim at once, then re-read so the screen holds what the store does. */
496	  protected claimSaved(claim: Claim): void {
497	    const sheet = this.session.sheet();
498	    if (!sheet) return;
499	    this.claims.update((list) =>
500	      list.some((c) => c.id === claim.id)
501	        ? list.map((c) => (c.id === claim.id ? claim : c))
502	        : [claim, ...list].sort((a, b) => b.id - a.id),
503	    );
504	    void this.read(sheet);
505	  }
506	
507	  /** Take a statement of the person, then re-read so their claims show the dues it bound them to. */
508	  protected async statement(person: Person): Promise<void> {
509	    this.rowError.set(null);
510	    this.patronError.set(null);
511	    const sheet = this.session.sheet();
512	    if (!sheet) return;
513	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/statement`;
514	    try {
515	      const saved = await firstValueFrom(this.http.post<Person>(url, null, this.session.headers()));
516	      if (this.session.sheet() === sheet) {
517	        this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
518	        void this.read(sheet);
519	      }
520	    } catch {
521	      this.rowError.set({ id: person.id, message: `A statement of ${person.name} could not be taken.` });
522	    }
523	  }
524	
525	  /** Retire the person from the typed date, or from the sheet's today when none is typed. */
526	  protected async retire(person: Person): Promise<void> {
527	    this.rowError.set(null);
528	    this.patronError.set(null);
529	    const sheet = this.session.sheet();
530	    if (!sheet) return;
531	    const from = (this.retireDates()[person.id] ?? '').trim();
532	    if (from && !/^\d{4}-\d{2}-\d{2}$/.test(from)) {
533	      this.rowError.set({ id: person.id, message: 'Pick a date to retire from, or leave it blank for today.' });
534	      return;
535	    }
536	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/retire`;
537	    try {
538	      const saved = await firstValueFrom(this.http.post<Person>(url, { from: from || null }, this.session.headers()));
539	      if (this.session.sheet() === sheet) {
540	        this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
541	        this.retireDates.update((dates) => ({ ...dates, [person.id]: '' }));
542	        void this.read(sheet);
543	      }
544	    } catch {
545	      this.rowError.set({ id: person.id, message: `${person.name} could not be retired.` });
546	    }
547	  }
548	
549	  /** Put the person on hold, or take them off it, then re-read so the totals show what the store holds. */
550	  protected async toggleHold(person: Person): Promise<void> {
551	    this.rowError.set(null);
552	    this.patronError.set(null);
553	    const sheet = this.session.sheet();
554	    if (!sheet) return;
555	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/hold`;
556	    try {
557	      const saved = await firstValueFrom(this.http.post<Person>(url, null, this.session.headers()));
558	      if (this.session.sheet() === sheet) {
559	        this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
560	        void this.read(sheet);
561	      }
562	    } catch {
563	      this.rowError.set({ id: person.id, message: `The hold of ${person.name} could not be changed.` });
564	    }
565	  }
566	
567	  protected edit(person: Person): void {
568	    this.rowError.set(null);
569	    this.patronError.set(null);
570	    this.editing.set(person.id);
571	    this.editingVersion = person.version;
572	    this.name.set(person.name);
573	    this.grade.set(this.gradeOf(person));
574	    this.gradeFrom.set('');
575	    this.error.set(null);
576	  }
577	
578	  protected reset(): void {
579	    this.editing.set(null);
580	    this.name.set('');
581	    this.grade.set('A');
582	    this.gradeFrom.set('');
583	    this.error.set(null);
584	  }
585	
586	  protected async submit(event: Event): Promise<void> {
587	    event.preventDefault();
588	    if (this.submitting) return;
589	    this.error.set(null);
590	    const sheet = this.session.sheet();
591	    if (!sheet) return;
592	    const editing = this.editing();
593	    const body = {
594	      name: this.name(),
595	      grade: this.grade(),
596	      gradeFrom: this.gradeFrom() || null,
597	      version: editing === null ? null : this.editingVersion,
598	    };
599	    if (!body.name.trim()) {
600	      this.error.set('Type a name for the person.');
601	      return;
602	    }
603	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people`;
604	    this.submitting = true;
605	    try {
606	      if (editing === null) {
607	        const added = await firstValueFrom(this.http.post<Person>(url, body, this.session.headers()));
608	        if (this.session.sheet() === sheet) this.people.update((list) => [...list, added]);
609	      } else {
610	        const saved = await firstValueFrom(
611	          this.http.put<Person>(`${url}/${editing}`, body, this.session.headers()),
612	        );
613	        if (this.session.sheet() === sheet) {
614	          this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
615	        }
616	      }
617	      if (this.session.sheet() === sheet) {
618	        this.reset();
619	        // Re-read the list so a slower read started before this change cannot overwrite it.
620	        void this.read(sheet);
621	      }
622	    } catch (e) {
623	      if (e instanceof HttpErrorResponse && e.status === 412 && editing !== null) {
624	        this.error.set('Someone else saved this person in the meantime. The form now shows their values.');
625	        await this.reloadEditor(sheet, editing);
626	      } else if (e instanceof HttpErrorResponse && e.status === 409) {
627	        this.error.set('Another person on the sheet already has that name.');
628	      } else {
629	        this.error.set(editing === null ? 'The person could not be added.' : 'The person could not be saved.');
630	      }
631	    } finally {
632	      this.submitting = false;
633	    }
634	  }
635	
636	  /**
637	   * Add a DRAFT claim of the amount, dated today with an empty note, for the person of the typed name; a name not on
638	   * the sheet adds the person first, with grade A. Refused as a whole when either would be.
639	   */
640	  protected async quickAdd(event: Event): Promise<void> {
641	    event.preventDefault();
642	    if (this.quickAdding) return;
643	    this.quickError.set(null);
644	    const sheet = this.session.sheet();
645	    if (!sheet) return;
646	    const name = this.quickName();
647	    if (!name.trim()) {
648	      this.quickError.set('Type the name of the person the claim is for.');
649	      return;
650	    }
651	    const amount = this.quickAmount().trim();
652	    if (!/^\d+(\.\d{1,2})?$/.test(amount)) {
653	      this.quickError.set('Type an amount of 0.00 or more, with at most two decimals.');
654	      return;
655	    }
656	    const url = `/api/sheets/${encodeURIComponent(sheet)}/quick-add`;
657	    this.quickAdding = true;
658	    try {
659	      const added = await firstValueFrom(this.http.post<Claim>(url, { name, amount }, this.session.headers()));
660	      if (this.session.sheet() === sheet) {
661	        this.quickName.set('');
662	        this.quickAmount.set('');
663	        // Re-reads the sheet, which also brings in a person the quick-add created.
664	        this.claimSaved(added);
665	      }
666	    } catch {
667	      const closed = periodOn(this.periods(), this.session.today() ?? '');
668	      const why = closed?.closed ? ` Today is in the closed period ${closed.name}.` : '';
669	      this.quickError.set('The claim could not be added.' + why);
670	    } finally {
671	      this.quickAdding = false;
672	    }
673	  }
674	
675	  /** Re-read the sheet and show the stored values of the person in the open editor. */
676	  private async reloadEditor(sheet: string, id: number): Promise<void> {
677	    await this.read(sheet);
678	    const person = this.people().find((p) => p.id === id);
679	    if (person && this.editing() === id && this.session.sheet() === sheet) {
680	      this.editingVersion = person.version;
681	      this.name.set(person.name);
682	      this.grade.set(this.gradeOf(person));
683	    }
684	  }
685	
686	  private async read(sheet: string): Promise<void> {
687	    const read = ++this.reads;
688	    const url = `/api/sheets/${encodeURIComponent(sheet)}`;
689	    const [list, claims, rates, periods] = await Promise.all([
690	      firstValueFrom(this.http.get<Person[]>(`${url}/people`, this.session.headers())),
691	      firstValueFrom(this.http.get<Claim[]>(`${url}/claims`, this.session.headers())),
692	      firstValueFrom(this.http.get<Rate[]>(`${url}/rates`, this.session.headers())),
693	      firstValueFrom(this.http.get<Period[]>(`${url}/periods`, this.session.headers())),
694	    ]).catch(() => [null, null, null, null]);
695	    // A later read wins over a slower earlier one.
696	    if (list && claims && rates && periods && read === this.reads && this.session.sheet() === sheet) {
697	      this.people.set(list);
698	      this.claims.set(claims);
699	      this.rates.set(rates);
700	      this.periods.set(periods);
701	    }
702	  }
703	}
